function longestConsecutive(nums) {
  const present = new Set(nums); // also removes duplicates
  let longest = 0;
  for (const num of present) {
    if (present.has(num - 1)) continue; // not the start of a run; its run is counted from the start
    let length = 1;
    while (present.has(num + length)) length++;
    if (length > longest) longest = length;
  }
  return longest;
}
